SELECT p.gender, i.age, EXTRACT(HOUR FROM i.intime) AS hour_of_admission, l.itemid AS lab_item_code, l.value AS lab_value, l.valueuom AS lab_unit, CASE WHEN l.value < 140 THEN '<140' WHEN l.value BETWEEN 140 AND 159 THEN '140-159' ELSE '≥160' END AS value_category, AVG(l.value) AS avg_value, MEDIAN(l.value) AS median_value, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY l.value) - PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY l.value) AS interquartile_range FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN labevents l ON i.stay_id = l.stay_id AND l.charttime BETWEEN i.intime AND i.outtime WHERE p.gender = 'F' AND i.age BETWEEN 65 AND 75 AND EXTRACT(HOUR FROM i.intime) <= 24 AND l.itemid = 848077 AND l.valueuom = 'mmHg' AND l.charttime <= i.outtime AND l.charttime >= i.intime AND l.value IS NOT NULL GROUP BY p.gender, i.age, hour_of_admission, lab_item_code, lab_value, lab_unit, value_category ORDER BY p.gender, i.age, hour_of_admission, value_category NULLS LAST;